import java.io.*;import java.net.ServerSocket;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import java.util.stream.*;
/** Repeats official Packet7 attack of type-10 and type-11 minecarts until Packet21 drops in two fresh worlds. */
public final class RemainingCartBreakCycle{
 private static final String ID="m404-remaining-cart-break";private final Path root=Paths.get("").toAbsolutePath().normalize(),smoke=root.resolve("smokes").resolve(ID),build=root.resolve(".worldline/smokes").resolve(ID);private final Properties config=new Properties(),artifact=new Properties();
 public static void main(String[]a){if(!Arrays.equals(a,new String[]{ID})){System.err.println("usage: java tools/smoke/RemainingCartBreakCycle.java "+ID);System.exit(2);}try{new RemainingCartBreakCycle().execute();}catch(Exception e){System.err.println("remaining cart break failed: "+e.getMessage());System.exit(1);}}
 private void execute()throws Exception{load(smoke.resolve("smoke.properties"),config);load(root.resolve("artifacts/minecraft-b1.7.3-server.properties"),artifact);require(ID.equals(value(config,"id"))&&value(config,"server.jar.sha256").equals(value(artifact,"expected.sha256"))&&value(config,"username").equals("CartBrk404")&&value(config,"username").length()<=16,"descriptor drift");Path official=root.resolve(value(artifact,"local.path")).normalize();verifyArtifact(official);recreate(build);Path classes=compile();Outcome first=run(classes,official,build.resolve("first")),second=run(classes,official,build.resolve("second"));require(first.signal.equals(second.signal)&&first.trace.equals(second.trace)&&first.signature.equals(second.signature),"fresh remaining-cart-break results diverged");require(first.signal.contains("type10")&&first.signal.contains("type11")&&first.signal.contains("packet21-328")&&first.signal.contains("packet21-54")&&!first.signal.contains("type12")&&first.trace.contains("packet7-attack")&&first.trace.contains("packet23-type10")&&first.trace.contains("packet23-type11")&&!first.trace.contains("packet100")&&!first.trace.contains("packet102")&&!first.trace.contains("packet15-dir255"),"remaining cart break collapsed to spawn-only, storage-window, crafts, or air-use");String expected=value(config,"expected.signature");if(expected.equals("pending")||Boolean.getBoolean("worldline.m404.diagnostic")){freeze(first);System.out.println("FROZEN");System.out.println("id="+ID);System.out.println("username="+value(config,"username"));System.out.println("signal="+first.signal);System.out.println("signature="+first.signature);return;}require(first.signal.equals(value(config,"expected.signal"))&&first.signature.equals(expected),"M404 frozen evidence drift");Files.writeString(build.resolve("evidence.txt"),"id="+ID+"\nservers=2\nclients=2\nfirst="+first.signal+"\nsecond="+second.signal+"\ntrace="+first.trace+"\nsignature="+first.signature+"\n",StandardCharsets.UTF_8);System.out.println("M404 remaining cart break passed");System.out.println("  "+first.signal);System.out.println("  signature: "+first.signature);System.out.println("FROZEN");System.out.println("id="+ID);System.out.println("username="+value(config,"username"));System.out.println("signal="+first.signal);System.out.println("signature="+first.signature);}
 private void freeze(Outcome first)throws Exception{String text="id="+ID+"\nseed="+value(config,"seed")+"\nusername="+value(config,"username")+"\nserver.jar.sha256="+value(config,"server.jar.sha256")+"\nchunk.x="+value(config,"chunk.x")+"\nchunk.z="+value(config,"chunk.z")+"\nexpected.signal="+first.signal+"\nexpected.signature="+first.signature+"\n";Files.writeString(smoke.resolve("smoke.properties"),text,StandardCharsets.UTF_8);}
 private Outcome run(Path classes,Path official,Path workspace)throws Exception{Exception last=null;for(int i=0;i<2;i++){try{if(Files.exists(workspace))recreate(workspace);String output=capture(root,Arrays.asList("java","-classpath",classes+separator()+product("api"),"worldline.smoke.remainingcartbreakb173.RemainingCartBreakSmoke",official.toString(),workspace.toString(),Integer.toString(freePort()),value(config,"seed"),value(config,"username"),value(config,"chunk.x"),value(config,"chunk.z")));return new Outcome(line(output,"WORLDLINE_M404_TRACE="),line(output,"WORLDLINE_M404_SIGNATURE="),line(output,"WORLDLINE_M404_SET="));}catch(Exception e){last=e;if(i==0&&eof(e)){Thread.sleep(5000L);continue;}throw e;}}throw last;}
 private Path compile()throws Exception{Path output=build.resolve("adapter-classes");Files.createDirectories(output);List<String>command=new ArrayList<>(Arrays.asList("javac","-encoding","UTF-8","--release","8","-Xlint:all,-options","-Werror","-classpath",product("api").toString(),"-d",output.toString()));command.addAll(javaFiles(root.resolve("adapters/b173-server/src/main/java")));command.addAll(javaFiles(smoke.resolve("src")));capture(root,command);return output;}
 private void verifyArtifact(Path p)throws Exception{require(Files.isRegularFile(p),"server artifact absent");require(Files.size(p)==Long.parseLong(value(artifact,"expected.bytes"))&&digest(p,"SHA-1").equals(value(artifact,"expected.sha1"))&&digest(p,"SHA-256").equals(value(artifact,"expected.sha256")),"server artifact drift");}private List<String>javaFiles(Path s)throws IOException{try(Stream<Path>p=Files.walk(s)){return p.filter(x->x.toString().endsWith(".java")).sorted().map(Path::toString).collect(Collectors.toList());}}private String capture(Path d,List<String>c)throws Exception{Process p=new ProcessBuilder(c).directory(d.toFile()).redirectErrorStream(true).start();String o=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(p.waitFor()!=0)throw new IllegalStateException(c.get(0)+" failed\n"+o);return o;}private void recreate(Path t)throws IOException{if(Files.exists(t)){require(t.startsWith(root.resolve(".worldline"))&&!t.equals(root),"unsafe build path");try(Stream<Path>p=Files.walk(t)){for(Path f:p.sorted(Comparator.reverseOrder()).collect(Collectors.toList()))Files.delete(f);}}Files.createDirectories(t);}private void load(Path p,Properties t)throws IOException{try(Reader r=Files.newBufferedReader(p,StandardCharsets.UTF_8)){t.load(r);}}private String value(Properties p,String k){String v=p.getProperty(k);require(v!=null&&!v.trim().isEmpty(),"missing "+k);return v.trim();}private String digest(Path p,String a)throws Exception{MessageDigest d=MessageDigest.getInstance(a);try(InputStream in=Files.newInputStream(p)){byte[]b=new byte[8192];int n;while((n=in.read(b))>=0)d.update(b,0,n);}return HexFormat.of().formatHex(d.digest());}private int freePort()throws IOException{try(ServerSocket s=new ServerSocket(0)){return s.getLocalPort();}}private Path product(String n){return root.resolve(".worldline/build/classes").resolve(n);}private String separator(){return System.getProperty("path.separator");}private String line(String o,String p){return o.lines().filter(x->x.startsWith(p)).findFirst().orElseThrow(()->new IllegalStateException("missing "+p+"\n"+o)).substring(p.length());}private static boolean eof(Exception e){for(Throwable t=e;t!=null;t=t.getCause()){if(t instanceof EOFException)return true;String m=t.getMessage();if(m!=null&&m.toUpperCase(Locale.ROOT).contains("EOF"))return true;}return false;}private static void require(boolean v,String m){if(!v)throw new IllegalStateException(m);}private static final class Outcome{final String trace,signature,signal;Outcome(String t,String s,String l){trace=t;signature=s;signal=l;}}
}
